"""Build display/analysis-only Phase-11 notebook."""
from pathlib import Path
import nbformat as nbf

R = Path(__file__).resolve().parents[2]
nb = nbf.v4.new_notebook()
nb.metadata = {
    'kernelspec': {'display_name': 'jup-venv', 'language': 'python', 'name': 'jup-venv'},
    'language_info': {'name': 'python', 'version': '3.11'},
    'phase': 11,
    'display_only': True
}

def md(s): return nbf.v4.new_markdown_cell(s)
def code(s): return nbf.v4.new_code_cell(s)

nb.cells = [
    md('# Phase 11 — KUB Global Baseline Failure Analysis\n\nVAL-only deterministic analysis. UNet++ is the fixed primary model; DeepLabV3+ is the FP comparator. **No training, tuning, ROI experiment, TEST access, or external-data access.**'),
    code("from pathlib import Path\nimport json,pandas as pd\nfrom IPython.display import display,Image\nROOT=Path.cwd().resolve(); ROOT=ROOT.parent if ROOT.name=='notebooks' else ROOT\nT=ROOT/'reports/tables'; F=ROOT/'reports/figures/phase11_kub_failure_analysis'; Q=ROOT/'reports/qualitative/phase11_kub_failure_analysis'\nx=pd.read_csv(T/'phase11_kub_failure_analysis_per_image.csv'); c=pd.read_csv(T/'phase11_kub_failure_analysis_per_component.csv'); cut=json.loads((ROOT/'reports/audits/phase11_failure_strata_definitions.json').read_text())\nprint('Governance PASS: phase4_v2; VAL only; threshold 0.5; TEST NOT ACCESSED')"),
    md('## Primary-model rationale and frozen reference'),
    code("display(pd.read_csv(T/'phase10_kub_model_comparison.csv'))\nprint('UNet++ fixed as primary from Phase 10; DeepLabV3+ retained for low-FP comparison.')"),
    md('## Primary-model training provenance\n\nUNet++ was trained and selected in Phase 10. Phase 11 performs no model training. These curves are loaded from finalized Phase-10 history for provenance (epochs completed: 92, best epoch: 77, early stopping epoch: 92).'),
    code("display(Image(filename=str(F/'phase11_unetpp_training_loss_provenance.png'),width=850))\ndisplay(Image(filename=str(F/'phase11_unetpp_val_dice_provenance.png'),width=850))\ndisplay(Image(filename=str(F/'phase11_unetpp_lr_provenance.png'),width=850))"),
    md('## FOV failure distributions and foreground scale'),
    code("display(x.groupby('FOV').agg(N=('sample_id','size'),Macro_Dice=('dice','mean'),Macro_IoU=('iou','mean'),Precision=('precision','mean'),Recall=('recall','mean')))\ndisplay(Image(filename=str(F/'phase11_dice_by_fov_distribution.png'),width=800))\ndisplay(Image(filename=str(F/'phase11_dice_vs_foreground_ratio.png'),width=850))"),
    md('## Category and original-space size failures'),
    code("display(x.groupby('category').agg(N=('sample_id','size'),Dice=('dice','mean'),IoU=('iou','mean'),Precision=('precision','mean'),Recall=('recall','mean')))\ndisplay(pd.read_csv(T/'phase11_kub_size_failure_summary.csv'))\ndisplay(Image(filename=str(F/'phase11_component_detection_vs_size.png'),width=900))"),
    md('## Multi-component failures and empty predictions'),
    code("display(pd.read_csv(T/'phase11_kub_multicomponent_failure.csv'))\ndisplay(x[x.empty_prediction][['sample_id','patient_id','category','FOV','component_count_original','dominant_object_stratum','gt_foreground_ratio','dice','hd95_valid']])\ndisplay(Image(filename=str(F/'phase11_multicomponent_failure.png'),width=950))"),
    md('## HD95 and precision–recall failure modes'),
    code("display(x.groupby(['FOV','hd95_valid']).size().rename('N').reset_index())\nprint(cut)\ndisplay(Image(filename=str(F/'phase11_hd95_by_fov.png'),width=800))\ndisplay(Image(filename=str(F/'phase11_precision_recall_failure_map.png'),width=800))"),
    md('## FP burden and DeepLabV3+ comparator'),
    code("display(pd.read_csv(T/'phase11_fp_unetpp_vs_deeplab.csv'))\ndisplay(Image(filename=str(F/'phase11_fp_burden_unetpp_vs_deeplab.png'),width=800))"),
    md('## Cross-model failure overlap'),
    code("display(pd.read_csv(T/'phase11_cross_model_failure_overlap.csv'))\ndisplay(Image(filename=str(F/'phase11_cross_model_failure_overlap.png'),width=950))"),
    md('## Patient-level clustering'),
    code("patients=pd.read_csv(T/'phase11_kub_failure_by_patient.csv'); display(patients.sort_values(['missed_original_components','worst_dice'],ascending=[False,True]).head(20)); print(f'VAL patients: {len(patients)}')"),
    md('## Reproducible failure taxonomy'),
    code("display(pd.read_csv(T/'phase11_kub_failure_summary.csv'))\ndisplay(Image(filename=str(F/'phase11_failure_taxonomy_counts.png'),width=1050))"),
    md('## Deterministic UNet++ failure panel'),
    code("display(Image(filename=str(Q/'phase11_unetpp_failure_panel.png'),width=1200))"),
    md('## Same-sample cross-model hard-case panel'),
    code("display(Image(filename=str(Q/'phase11_cross_model_hard_case_panel.png'),width=1200))"),
    md('## Phase-12 motivation\n\nFULL_FIELD performance remains materially below ROI_CROP performance, residual TINY/SMALL misses persist, and multi-component partial/complete misses remain. These patterns provide evidence to **test whether increased effective local resolution can recover missed targets** using an Oracle ROI/zoom upper-bound study. They do not establish that ROI will solve them.'),
    md('## Limitations and phase control\n\nSingle seed and one VAL split; descriptive quantiles only; no significance or deployment claims. Original-space size identity is distinct from 512×512 evaluation-space object counts. **TEST NOT ACCESSED. Phase 12 was not executed. STOP.**')
]

out = R / 'notebooks/09_kub_failure_analysis.ipynb'
out.write_text(nbf.writes(nb), encoding='utf-8')
print(out)


